1	import { z } from "zod";
2	import { nanoid } from "nanoid";
3	import {
4	  BB_DESKTOP_BROWSER_MAX_TITLE_LENGTH,
5	  BB_DESKTOP_BROWSER_MAX_URL_LENGTH,
6	} from "@bb/desktop-contract";
7	import {
8	  areFilePreviewLineRangesEqual,
9	  areEnvironmentFilePreviewSourcesEqual,
10	  type EnvironmentFilePreviewSource,
11	  type FilePreviewLineRange,
12	  type HostFileTabState,
13	  type ThreadStorageFileTabState,
14	  type WorkspaceFilePreviewStatusLabel,
15	  type WorkspaceFileTabState,
16	} from "./file-preview";
17	
18	export const FIXED_PANEL_TABS_STATE_STORAGE_PREFIX =
19	  "bb.thread.fixedPanelTabsState";
20	export const FIXED_PANEL_TABS_STATE_STORAGE_VERSION = 1;
21	export const FIXED_PANEL_TABS_IDLE_EXPIRY_MS = 14 * 24 * 60 * 60 * 1000;
22	
23	const SECONDARY_PANEL_TAB_ID_ENVIRONMENT_NONE = "none";
24	const THREAD_INFO_TAB_ID = "thread-info:thread-info:none";
25	const GIT_DIFF_TAB_ID = "git-diff:git-diff:none";
26	const PULL_REQUEST_TAB_ID = "pull-request:pull-request:none";
27	const NEW_TAB_TAB_ID = "new-tab:new-tab:none";
28	
29	const environmentFilePreviewSourceSchema: z.ZodType<EnvironmentFilePreviewSource> =
30	  z.discriminatedUnion("kind", [
31	    z
32	      .object({
33	        kind: z.literal("working-tree"),
34	      })
35	      .strict(),
36	    z
37	      .object({
38	        kind: z.literal("head"),
39	      })
40	      .strict(),
41	    z
42	      .object({
43	        kind: z.literal("merge-base"),
44	        ref: z.string().min(1),
45	      })
46	      .strict(),
47	  ]);
48	const workspaceFilePreviewStatusLabelSchema: z.ZodType<WorkspaceFilePreviewStatusLabel | null> =
49	  z.literal("deleted").nullable();
50	const filePreviewLineRangeSchema: z.ZodType<FilePreviewLineRange> = z
51	  .object({
52	    endLineNumber: z.number().int().positive(),
53	    startLineNumber: z.number().int().positive(),
54	  })
55	  .strict()
56	  .refine((range) => range.startLineNumber <= range.endLineNumber);
57	const threadInfoFixedPanelTabSchema = z
58	  .object({
59	    id: z.string().min(1),
60	    kind: z.literal("thread-info"),
61	  })
62	  .strict();
63	const gitDiffFixedPanelTabSchema = z
64	  .object({
65	    id: z.string().min(1),
66	    kind: z.literal("git-diff"),
67	  })
68	  .strict();
69	const pullRequestFixedPanelTabSchema = z
70	  .object({
71	    id: z.string().min(1),
72	    kind: z.literal("pull-request"),
73	  })
74	  .strict();
75	const workspaceFilePreviewFixedPanelTabSchema = z
76	  .object({
77	    environmentId: z.string().min(1).nullable(),
78	    id: z.string().min(1),
79	    kind: z.literal("workspace-file-preview"),
80	    lineRange: filePreviewLineRangeSchema.nullable().default(null),
81	    path: z.string().min(1),
82	    projectId: z.string().min(1).nullable().default(null),
83	    source: environmentFilePreviewSourceSchema,
84	    statusLabel: workspaceFilePreviewStatusLabelSchema,
85	  })
86	  .strict();
87	const hostFilePreviewFixedPanelTabSchema = z
88	  .object({
89	    environmentId: z.string().min(1).nullable().default(null),
90	    id: z.string().min(1),
91	    kind: z.literal("host-file-preview"),
92	    lineRange: filePreviewLineRangeSchema.nullable().default(null),
93	    path: z.string().min(1),
94	    threadId: z.string().min(1).nullable().default(null),
95	  })
96	  .strict();
97	const threadStorageFilePreviewFixedPanelTabSchema = z
98	  .object({
99	    environmentId: z.string().min(1).nullable().default(null),
100	    id: z.string().min(1),
101	    isPinned: z.boolean(),
102	    kind: z.literal("thread-storage-file-preview"),
103	    lineRange: filePreviewLineRangeSchema.nullable().default(null),
104	    path: z.string().min(1),
105	    threadId: z.string().min(1).nullable().default(null),
106	  })
107	  .strict();
108	const browserFixedPanelTabSchema = z
109	  .object({
110	    environmentId: z.string().min(1).nullable().default(null),
111	    id: z.string().min(1),
112	    kind: z.literal("browser"),
113	    title: z
114	      .string()
115	      .min(1)
116	      .max(BB_DESKTOP_BROWSER_MAX_TITLE_LENGTH)
117	      .nullable(),
118	    url: z.string().max(BB_DESKTOP_BROWSER_MAX_URL_LENGTH),
119	  })
120	  .strict();
121	const newTabFixedPanelTabSchema = z
122	  .object({
123	    id: z.string().min(1),
124	    kind: z.literal("new-tab"),
125	  })
126	  .strict();
127	const terminalFixedPanelTabSchema = z
128	  .object({
129	    id: z.string().min(1),
130	    kind: z.literal("terminal"),
131	    terminalId: z.string().min(1),
132	  })
133	  .strict();
134	const pluginPanelFixedPanelTabSchema = z
135	  .object({
136	    actionId: z.string().min(1),
137	    id: z.string().min(1),
138	    kind: z.literal("plugin-panel"),
139	    paramsJson: z.string().nullable(),
140	    pluginId: z.string().min(1),
141	    title: z.string().min(1),
142	  })
143	  .strict();
144	const secondaryFixedPanelTabSchema = z.union([
145	  threadInfoFixedPanelTabSchema,
146	  gitDiffFixedPanelTabSchema,
147	  pullRequestFixedPanelTabSchema,
148	  pluginPanelFixedPanelTabSchema,
149	  workspaceFilePreviewFixedPanelTabSchema,
150	  hostFilePreviewFixedPanelTabSchema,
151	  threadStorageFilePreviewFixedPanelTabSchema,
152	  browserFixedPanelTabSchema,
153	  newTabFixedPanelTabSchema,
154	  terminalFixedPanelTabSchema,
155	]);
156	/**
157	 * The native side chat is gone, but persisted panel state can still hold its
158	 * tabs. Drop them at the parse boundary so old state loads and the removed
159	 * tabs simply disappear from the strip.
160	 */
161	const secondaryFixedPanelTabsSchema = z.preprocess(
162	  (value) =>
163	    Array.isArray(value)
164	      ? value.filter(
165	          (tab) =>
166	            !(
167	              typeof tab === "object" &&
168	              tab !== null &&
169	              (tab as { kind?: unknown }).kind === "side-chat"
170	            ),
171	        )
172	      : value,
173	  z.array(secondaryFixedPanelTabSchema),
174	);
175	const secondaryFixedPanelTabGroupStateSchema = z
176	  .object({
177	    tabs: secondaryFixedPanelTabsSchema,
178	    activeTabId: z.string().min(1).nullable(),
179	    isOpen: z.boolean(),
180	  })
181	  .strict();
182	const fixedPanelTabsStateSchema = z
183	  .object({
184	    version: z.literal(FIXED_PANEL_TABS_STATE_STORAGE_VERSION),
185	    secondary: secondaryFixedPanelTabGroupStateSchema,
186	    lastUsedAt: z.number().int().nonnegative(),
187	  })
188	  .passthrough();
189	
190	export interface ThreadInfoFixedPanelTab {
191	  id: string;
192	  kind: "thread-info";
193	}
194	
195	export interface GitDiffFixedPanelTab {
196	  id: string;
197	  kind: "git-diff";
198	}
199	
200	export interface PullRequestFixedPanelTab {
201	  id: string;
202	  kind: "pull-request";
203	}
204	
205	/**
206	 * A panel tab opened by a plugin `threadPanelAction` (plugin design §5.2) —
207	 * a closable file-strip tab like a terminal, not a fixed view.
208	 * `paramsJson` is the JSON-serialized `openPanel` params (null = none); it
209	 * is part of the tab identity, so the same action can hold several tabs
210	 * with different params while identical re-opens focus the existing one.
211	 * If the plugin/action is gone on restore the content degrades to a
212	 * placeholder.
213	 */
214	export interface PluginPanelFixedPanelTab {
215	  actionId: string;
216	  id: string;
217	  kind: "plugin-panel";
218	  paramsJson: string | null;
219	  pluginId: string;
220	  title: string;
221	}
222	
223	export interface WorkspaceFilePreviewFixedPanelTab {
224	  environmentId: string | null;
225	  id: string;
226	  kind: "workspace-file-preview";
227	  lineRange: FilePreviewLineRange | null;
228	  path: string;
229	  projectId: string | null;
230	  source: EnvironmentFilePreviewSource;
231	  statusLabel: WorkspaceFilePreviewStatusLabel | null;
232	}
233	
234	export interface HostFilePreviewFixedPanelTab {
235	  environmentId: string | null;
236	  id: string;
237	  kind: "host-file-preview";
238	  lineRange: FilePreviewLineRange | null;
239	  path: string;
240	  threadId: string | null;
241	}
242	
243	export interface ThreadStorageFilePreviewFixedPanelTab {
244	  environmentId: string | null;
245	  id: string;
246	  isPinned: boolean;
247	  kind: "thread-storage-file-preview";
248	  lineRange: FilePreviewLineRange | null;
249	  path: string;
250	  threadId: string | null;
251	}
252	
253	/**
254	 * A web browser tab hosted by a native Electron `WebContentsView` (desktop
255	 * only). `url` is the last-loaded page (empty string = the new-tab screen) and
256	 * `title` is the last title pushed from the view, so the tab pill keeps its
257	 * label while inactive and across reloads. Favicons are intentionally not
258	 * persisted/rendered (untrusted remote URL); the pill shows a generic globe.
259	 * Live loading state is not persisted — it is held by the active tab's chrome.
260	 */
261	export interface BrowserFixedPanelTab {
262	  environmentId: string | null;
263	  id: string;
264	  kind: "browser";
265	  title: string | null;
266	  url: string;
267	}
268	
269	export interface NewTabFixedPanelTab {
270	  id: string;
271	  kind: "new-tab";
272	}
273	
274	export interface TerminalFixedPanelTab {
275	  id: string;
276	  kind: "terminal";
277	  terminalId: string;
278	}
279	
280	export type SecondaryFixedPanelTab =
281	  | ThreadInfoFixedPanelTab
282	  | GitDiffFixedPanelTab
283	  | PullRequestFixedPanelTab
284	  | PluginPanelFixedPanelTab
285	  | WorkspaceFilePreviewFixedPanelTab
286	  | HostFilePreviewFixedPanelTab
287	  | ThreadStorageFilePreviewFixedPanelTab
288	  | BrowserFixedPanelTab
289	  | NewTabFixedPanelTab
290	  | TerminalFixedPanelTab;
291	
292	/**
293	 * The subset of secondary-panel tabs rendered as closable file tabs in the tab
294	 * strip. Excludes thread-info and git-diff, which are fixed views toggled
295	 * separately rather than ordered alongside opened files.
296	 */
297	export type SecondaryFileFixedPanelTab =
298	  | WorkspaceFilePreviewFixedPanelTab
299	  | HostFilePreviewFixedPanelTab
300	  | ThreadStorageFilePreviewFixedPanelTab
301	  | BrowserFixedPanelTab
302	  | NewTabFixedPanelTab
303	  | TerminalFixedPanelTab
304	  | PluginPanelFixedPanelTab;
305	
306	export type FixedPanelTab = SecondaryFixedPanelTab;
307	
308	export interface FixedPanelTabGroupState {
309	  tabs: readonly FixedPanelTab[];
310	  activeTabId: string | null;
311	}
312	
313	export interface FixedSecondaryPanelTabGroupState extends FixedPanelTabGroupState {
314	  isOpen: boolean;
315	}
316	
317	export interface FixedPanelTabsState {
318	  version: typeof FIXED_PANEL_TABS_STATE_STORAGE_VERSION;
319	  secondary: FixedSecondaryPanelTabGroupState;
320	  lastUsedAt: number;
321	}
322	
323	interface FixedPanelTabsStorageKeyArgs {
324	  threadId: string;
325	}
326	
327	interface CreateFixedPanelTabsStateArgs {
328	  lastUsedAt?: number;
329	  secondary?: FixedSecondaryPanelTabGroupState;
330	}
331	
