354	}
355	
356	interface NormalizeFixedPanelTabsStateArgs {
357	  state: FixedPanelTabsState;
358	}
359	
360	interface StripTransientFixedPanelTabsStateForStorageArgs {
361	  state: FixedPanelTabsState;
362	}
363	
364	interface NormalizeFixedPanelTabGroupStateArgs {
365	  group: FixedPanelTabGroupState;
366	}
367	
368	interface CreateThreadStorageFilePreviewFixedPanelTabArgs {
369	  environmentId: string | null;
370	  isPinned: boolean;
371	  tab: ThreadStorageFileTabState;
372	  threadId: string;
373	}
374	
375	interface CreateHostFilePreviewFixedPanelTabArgs {
376	  environmentId: string;
377	  tab: HostFileTabState;
378	  threadId: string;
379	}
380	
381	interface CreateBrowserFixedPanelTabArgs {
382	  environmentId: string | null;
383	  url: string;
384	}
