397	  actionId: string;
398	  paramsJson: string | null;
399	  pluginId: string;
400	  title: string;
401	}
402	
403	interface BuildFixedPanelTabIdArgs {
404	  environmentId: string | null;
405	  kind: FixedPanelTab["kind"];
406	  path: string;
407	}
408	
409	interface BuildWorkspaceFilePreviewTabIdArgs {
410	  environmentId: string | null;
411	  path: string;
412	  projectId: string | null;
413	}
