431	function getLocalStorage(): Storage | null {
432	  if (typeof window === "undefined") {
433	    return null;
434	  }
435	  return window.localStorage;
436	}
437	
438	function normalizeStorageSegment(value: string): string {
439	  return encodeURIComponent(value.trim());
440	}
441	
442	function decodeStorageSegment(value: string): string {
443	  try {
444	    return decodeURIComponent(value);
445	  } catch {
446	    return value;
447	  }
448	}
449	
450	export function buildFixedPanelTabId({
451	  environmentId,
452	  kind,
453	  path,
454	}: BuildFixedPanelTabIdArgs): string {
455	  return [
456	    kind,
457	    encodeURIComponent(path),
458	    encodeURIComponent(
459	      environmentId ?? SECONDARY_PANEL_TAB_ID_ENVIRONMENT_NONE,
460	    ),
461	  ].join(":");
462	}
463	
464	function buildWorkspaceFilePreviewTabId({
465	  environmentId,
466	  path,
467	  projectId,
468	}: BuildWorkspaceFilePreviewTabIdArgs): string {
469	  return buildFixedPanelTabId({
470	    environmentId: environmentId ?? (projectId ? `project:${projectId}` : null),
471	    kind: "workspace-file-preview",
472	    path,
473	  });
474	}
475	
476	function buildHostFilePreviewTabId({
477	  environmentId,
478	  path,
479	  threadId,
480	}: BuildHostFilePreviewTabIdArgs): string {
481	  if (threadId === null || environmentId === null) {
482	    return buildFixedPanelTabId({
483	      environmentId: null,
484	      kind: "host-file-preview",
485	      path,
486	    });
487	  }
488	  return buildFixedPanelTabId({
489	    environmentId: `thread:${threadId}:environment:${environmentId}`,
490	    kind: "host-file-preview",
491	    path,
492	  });
493	}
494	
495	function buildThreadStorageFilePreviewTabId({
496	  path,
497	  threadId,
498	}: BuildThreadStorageFilePreviewTabIdArgs): string {
499	  return buildFixedPanelTabId({
500	    environmentId: threadId === null ? null : `thread:${threadId}`,
501	    kind: "thread-storage-file-preview",
502	    path,
503	  });
504	}
505	
506	export function createThreadInfoFixedPanelTab(): ThreadInfoFixedPanelTab {
507	  return {
508	    id: THREAD_INFO_TAB_ID,
509	    kind: "thread-info",
510	  };
511	}
512	
513	export function createGitDiffFixedPanelTab(): GitDiffFixedPanelTab {
514	  return {
515	    id: GIT_DIFF_TAB_ID,
516	    kind: "git-diff",
517	  };
518	}
519	
520	export function createPullRequestFixedPanelTab(): PullRequestFixedPanelTab {
521	  return {
522	    id: PULL_REQUEST_TAB_ID,
523	    kind: "pull-request",
524	  };
525	}
526	
527	export function createPluginPanelFixedPanelTab({
528	  actionId,
529	  paramsJson,
530	  pluginId,
531	  title,
532	}: CreatePluginPanelFixedPanelTabArgs): PluginPanelFixedPanelTab {
533	  return {
534	    actionId,
535	    // Params are part of the identity (title is not): re-opening the same
536	    // action with the same params focuses the existing tab, different
537	    // params open a sibling tab.
538	    id: buildFixedPanelTabId({
539	      environmentId: null,
540	      kind: "plugin-panel",
541	      path: `${pluginId}:${actionId}:${paramsJson ?? ""}`,
542	    }),
543	    kind: "plugin-panel",
544	    paramsJson,
545	    pluginId,
546	    title,
547	  };
548	}
549	
550	export function createWorkspaceFilePreviewFixedPanelTab({
551	  environmentId,
552	  projectId,
553	  tab,
554	}: CreateWorkspaceFilePreviewFixedPanelTabArgs): WorkspaceFilePreviewFixedPanelTab {
555	  return {
556	    environmentId,
557	    id: buildWorkspaceFilePreviewTabId({
558	      environmentId,
559	      path: tab.path,
560	      projectId,
561	    }),
562	    kind: "workspace-file-preview",
563	    lineRange: tab.lineRange,
564	    path: tab.path,
565	    projectId,
566	    source: tab.source,
567	    statusLabel: tab.statusLabel,
568	  };
569	}
570	
571	export function createHostFilePreviewFixedPanelTab({
572	  environmentId,
573	  tab,
574	  threadId,
575	}: CreateHostFilePreviewFixedPanelTabArgs): HostFilePreviewFixedPanelTab {
576	  return {
577	    environmentId,
578	    id: buildHostFilePreviewTabId({
579	      environmentId,
580	      path: tab.path,
581	      threadId,
582	    }),
583	    kind: "host-file-preview",
584	    lineRange: tab.lineRange,
585	    path: tab.path,
586	    threadId,
587	  };
588	}
589	
590	export function createThreadStorageFilePreviewFixedPanelTab({
591	  environmentId,
592	  isPinned,
593	  tab,
594	  threadId,
595	}: CreateThreadStorageFilePreviewFixedPanelTabArgs): ThreadStorageFilePreviewFixedPanelTab {
596	  return {
597	    environmentId,
598	    id: buildThreadStorageFilePreviewTabId({
599	      path: tab.path,
600	      threadId,
601	    }),
602	    isPinned,
603	    kind: "thread-storage-file-preview",
604	    lineRange: tab.lineRange,
605	    path: tab.path,
606	    threadId,
607	  };
608	}
609	
610	/**
611	 * Browser tabs get a fresh unique id per instance — the URL is mutable (it
612	 * changes on every navigation), so it cannot serve as a stable identity the way
613	 * a file path does.
614	 */
615	export function createBrowserFixedPanelTab({
616	  environmentId,
617	  url,
618	}: CreateBrowserFixedPanelTabArgs): BrowserFixedPanelTab {
619	  const browserInstanceId = nanoid();
620	  return {
621	    environmentId,
622	    id: buildFixedPanelTabId({
623	      environmentId,
624	      kind: "browser",
625	      path: browserInstanceId,
626	    }),
627	    kind: "browser",
628	    title: null,
629	    url,
630	  };
631	}
632	
633	export function createNewTabFixedPanelTab(): NewTabFixedPanelTab {
634	  return {
635	    id: NEW_TAB_TAB_ID,
636	    kind: "new-tab",
637	  };
638	}
639	
640	export function createTerminalFixedPanelTab({
641	  terminalId,
642	}: CreateTerminalFixedPanelTabArgs): TerminalFixedPanelTab {
643	  return {
644	    id: buildFixedPanelTabId({
645	      environmentId: null,
646	      kind: "terminal",
647	      path: terminalId,
648	    }),
649	    kind: "terminal",
650	    terminalId,
651	  };
652	}
653	
654	function normalizeFixedPanelTabId(tab: FixedPanelTab): FixedPanelTab {
655	  switch (tab.kind) {
656	    case "thread-info":
657	      return tab.id === THREAD_INFO_TAB_ID
658	        ? tab
659	        : {
660	            ...tab,
661	            id: THREAD_INFO_TAB_ID,
662	          };
663	    case "git-diff":
664	      return tab.id === GIT_DIFF_TAB_ID
665	        ? tab
666	        : {
667	            ...tab,
668	            id: GIT_DIFF_TAB_ID,
669	          };
670	    case "pull-request":
671	      return tab.id === PULL_REQUEST_TAB_ID
672	        ? tab
673	        : {
674	            ...tab,
675	            id: PULL_REQUEST_TAB_ID,
676	          };
677	    case "workspace-file-preview": {
678	      const id = buildWorkspaceFilePreviewTabId({
679	        environmentId: tab.environmentId,
680	        path: tab.path,
681	        projectId: tab.projectId,
682	      });
683	      return tab.id === id ? tab : { ...tab, id };
684	    }
685	    case "host-file-preview": {
686	      const id = buildHostFilePreviewTabId({
687	        environmentId: tab.environmentId,
688	        path: tab.path,
689	        threadId: tab.threadId,
690	      });
691	      return tab.id === id ? tab : { ...tab, id };
692	    }
693	    case "thread-storage-file-preview": {
694	      const id = buildThreadStorageFilePreviewTabId({
695	        path: tab.path,
696	        threadId: tab.threadId,
697	      });
698	      return tab.id === id ? tab : { ...tab, id };
699	    }
700	    case "browser": {
701	      const idSegments = tab.id.split(":");
702	      const browserPath =
703	        idSegments.length === 3 && idSegments[0] === "browser"
704	          ? decodeStorageSegment(idSegments[1] ?? "")
705	          : tab.id;
706	      const id = buildFixedPanelTabId({
707	        environmentId: tab.environmentId,
708	        kind: tab.kind,
709	        path: browserPath,
710	      });
711	      return tab.id === id ? tab : { ...tab, id };
712	    }
713	    case "new-tab":
714	      return tab.id === NEW_TAB_TAB_ID
715	        ? tab
716	        : {
717	            ...tab,
718	            id: NEW_TAB_TAB_ID,
719	          };
720	    case "plugin-panel": {
721	      const id = createPluginPanelFixedPanelTab({
722	        actionId: tab.actionId,
723	        paramsJson: tab.paramsJson,
724	        pluginId: tab.pluginId,
725	        title: tab.title,
726	      }).id;
727	      return tab.id === id ? tab : { ...tab, id };
728	    }
729	    case "terminal": {
730	      const id = buildFixedPanelTabId({
731	        environmentId: null,
732	        kind: tab.kind,
733	        path: tab.terminalId,
734	      });
735	      return tab.id === id ? tab : { ...tab, id };
736	    }
737	  }
738	}
739	
740	function isTransientFixedPanelTab(tab: FixedPanelTab): boolean {
741	  return tab.kind === "new-tab";
742	}
743	
744	function normalizeFixedPanelTabGroupState({
745	  group,
746	}: NormalizeFixedPanelTabGroupStateArgs): NormalizeFixedPanelTabGroupStateResult {
747	  const seenTabIds = new Set<string>();
748	  const tabs: FixedPanelTab[] = [];
749	  let activeTabId: string | null = null;
750	  for (const tab of group.tabs) {
751	    const normalizedTab = normalizeFixedPanelTabId(tab);
752	    if (
753	      isTransientFixedPanelTab(normalizedTab) ||
754	      seenTabIds.has(normalizedTab.id)
755	    ) {
756	      continue;
757	    }
758	    seenTabIds.add(normalizedTab.id);
759	    tabs.push(normalizedTab);
760	    if (
761	      group.activeTabId !== null &&
762	      (tab.id === group.activeTabId || normalizedTab.id === group.activeTabId)
763	    ) {
764	      activeTabId = normalizedTab.id;
765	    }
766	  }
767	
768	  return {
769	    tabs,
770	    activeTabId,
771	  };
772	}
773	
774	function normalizeFixedSecondaryPanelTabGroupState(
775	  group: FixedSecondaryPanelTabGroupState,
776	): FixedSecondaryPanelTabGroupState {
777	  return {
778	    ...normalizeFixedPanelTabGroupState({
779	      group,
780	    }),
781	    isOpen: group.isOpen,
782	  };
783	}
784	
785	function stripTransientFixedPanelTabForStorage(
786	  tab: FixedPanelTab,
787	): FixedPanelTab {
788	  switch (tab.kind) {
789	    case "workspace-file-preview":
790	    case "host-file-preview":
791	    case "thread-storage-file-preview":
792	      return {
793	        ...tab,
794	        lineRange: null,
795	      };
796	    case "thread-info":
797	    case "git-diff":
798	    case "pull-request":
799	    case "plugin-panel":
800	    case "browser":
801	    case "new-tab":
802	    case "terminal":
803	      return tab;
804	  }
805	}
806	
807	function stripTransientFixedPanelTabsStateForStorage({
808	  state,
809	}: StripTransientFixedPanelTabsStateForStorageArgs): FixedPanelTabsState {
810	  return {
811	    ...state,
812	    secondary: {
813	      ...state.secondary,
814	      tabs: state.secondary.tabs.map(stripTransientFixedPanelTabForStorage),
815	    },
816	  };
817	}
818	
819	export function normalizeFixedPanelTabsState({
820	  state,
821	}: NormalizeFixedPanelTabsStateArgs): FixedPanelTabsState {
822	  const normalizedSecondary = normalizeFixedSecondaryPanelTabGroupState(
823	    state.secondary,
824	  );
825	
826	  return {
827	    version: state.version,
828	    secondary: normalizedSecondary,
829	    lastUsedAt: state.lastUsedAt,
830	  };
831	}
832	
833	export function createEmptyFixedPanelTabsState(
834	  args: CreateFixedPanelTabsStateArgs = {},
835	): FixedPanelTabsState {
836	  return normalizeFixedPanelTabsState({
837	    state: {
838	      version: FIXED_PANEL_TABS_STATE_STORAGE_VERSION,
839	      secondary: args.secondary ?? {
840	        tabs: [],
841	        activeTabId: null,
842	        isOpen: false,
843	      },
844	      lastUsedAt: args.lastUsedAt ?? 0,
845	    },
846	  });
847	}
848	
849	export const EMPTY_FIXED_PANEL_TABS_STATE = createEmptyFixedPanelTabsState();
850	
851	export function getFixedPanelTabsStateStorageKey({
852	  threadId,
853	}: FixedPanelTabsStorageKeyArgs): string {
854	  return `${FIXED_PANEL_TABS_STATE_STORAGE_PREFIX}-${normalizeStorageSegment(
855	    threadId,
856	  )}-${FIXED_PANEL_TABS_STATE_STORAGE_VERSION}`;
857	}
858	
859	export function isFixedPanelTabsStateStorageKey(key: string): boolean {
860	  return key.startsWith(`${FIXED_PANEL_TABS_STATE_STORAGE_PREFIX}-`);
861	}
862	
863	export function isFixedPanelTabsStateExpired({
864	  now,
865	  state,
866	}: IsFixedPanelTabsStateExpiredArgs): boolean {
867	  return now - state.lastUsedAt > FIXED_PANEL_TABS_IDLE_EXPIRY_MS;
868	}
869	
870	export function parseFixedPanelTabsState({
871	  initialValue,
872	  now,
873	  storedValue,
874	}: ParseFixedPanelTabsStateArgs): FixedPanelTabsState {
875	  return parseFixedPanelTabsStateForStorage({
876	    initialValue,
877	    now,
878	    storedValue,
879	  }).state;
880	}
881	
882	function parseFixedPanelTabsStateForStorage({
883	  initialValue,
884	  now,
885	  storedValue,
886	}: ParseFixedPanelTabsStateArgs): ParseFixedPanelTabsStateForStorageResult {
887	  if (storedValue === null) {
888	    return {
889	      shouldPrune: false,
890	      state: initialValue,
891	    };
892	  }
893	
894	  let parsedValue: unknown;
895	  try {
896	    parsedValue = JSON.parse(storedValue);
897	  } catch {
898	    return {
899	      shouldPrune: true,
900	      state: initialValue,
901	    };
902	  }
903	
904	  const stateResult = fixedPanelTabsStateSchema.safeParse(parsedValue);
905	  if (!stateResult.success) {
906	    return {
907	      shouldPrune: true,
908	      state: initialValue,
909	    };
910	  }
911	
912	  const normalizedState = stripTransientFixedPanelTabsStateForStorage({
913	    state: normalizeFixedPanelTabsState({
914	      state: stateResult.data,
915	    }),
916	  });
917	  if (isFixedPanelTabsStateExpired({ now, state: normalizedState })) {
918	    return {
919	      shouldPrune: true,
920	      state: initialValue,
921	    };
922	  }
923	
924	  return {
925	    shouldPrune: false,
926	    state: normalizedState,
927	  };
928	}
929	
930	export function serializeFixedPanelTabsState({
931	  state,
932	}: SerializeFixedPanelTabsStateArgs): string {
933	  return JSON.stringify(
934	    stripTransientFixedPanelTabsStateForStorage({
935	      state: normalizeFixedPanelTabsState({ state }),
936	    }),
937	  );
938	}
939	
940	export function pruneFixedPanelTabsStorage({
941	  now,
942	}: PruneFixedPanelTabsStorageArgs): void {
943	  const localStorage = getLocalStorage();
944	  if (!localStorage) {
945	    return;
946	  }
947	
948	  const keys: string[] = [];
949	  for (let index = 0; index < localStorage.length; index += 1) {
950	    const key = localStorage.key(index);
951	    if (key && isFixedPanelTabsStateStorageKey(key)) {
952	      keys.push(key);
953	    }
954	  }
955	
956	  for (const key of keys) {
957	    const result = parseFixedPanelTabsStateForStorage({
958	      initialValue: EMPTY_FIXED_PANEL_TABS_STATE,
959	      now,
960	      storedValue: localStorage.getItem(key),
961	    });
962	    if (result.shouldPrune) {
963	      localStorage.removeItem(key);
964	    }
965	  }
966	}
967	
968	export function areFixedPanelTabsEquivalent(
969	  a: FixedPanelTab,
970	  b: FixedPanelTab,
971	): boolean {
972	  if (a.id !== b.id || a.kind !== b.kind) {
973	    return false;
974	  }
975	  switch (a.kind) {
976	    case "thread-info":
977	    case "git-diff":
978	    case "pull-request":
979	    case "new-tab":
980	      return true;
981	    case "plugin-panel":
982	      return (
983	        b.kind === "plugin-panel" &&
984	        a.pluginId === b.pluginId &&
985	        a.actionId === b.actionId &&
986	        a.paramsJson === b.paramsJson &&
987	        a.title === b.title
988	      );
989	    case "workspace-file-preview":
990	      return (
991	        b.kind === "workspace-file-preview" &&
992	        a.environmentId === b.environmentId &&
993	        areFilePreviewLineRangesEqual({
994	          a: a.lineRange,
995	          b: b.lineRange,
996	        }) &&
997	        a.path === b.path &&
998	        a.projectId === b.projectId &&
999	        areEnvironmentFilePreviewSourcesEqual(a.source, b.source) &&
1000	        a.statusLabel === b.statusLabel
1001	      );
1002	    case "host-file-preview":
1003	      return (
1004	        b.kind === "host-file-preview" &&
1005	        a.environmentId === b.environmentId &&
1006	        areFilePreviewLineRangesEqual({
1007	          a: a.lineRange,
1008	          b: b.lineRange,
1009	        }) &&
1010	        a.path === b.path &&
1011	        a.threadId === b.threadId
1012	      );
1013	    case "browser":
1014	      return (
1015	        b.kind === "browser" &&
1016	        a.environmentId === b.environmentId &&
1017	        a.url === b.url &&
1018	        a.title === b.title
1019	      );
1020	    case "thread-storage-file-preview":
1021	      return (
1022	        b.kind === "thread-storage-file-preview" &&
1023	        a.environmentId === b.environmentId &&
1024	        a.isPinned === b.isPinned &&
1025	        areFilePreviewLineRangesEqual({
1026	          a: a.lineRange,
1027	          b: b.lineRange,
1028	        }) &&
1029	        a.path === b.path &&
1030	        a.threadId === b.threadId
1031	      );
1032	    case "terminal":
1033	      return b.kind === "terminal" && a.terminalId === b.terminalId;
1034	  }
